question.solution:
def best_fit_alloc(free_list, size):
    pick = -1
    for i in range(len(free_list)):
        if free_list[i][1] >= size:
            if pick == -1 or free_list[i][1] < free_list[pick][1] or (
                    free_list[i][1] == free_list[pick][1]
                    and free_list[i][0] < free_list[pick][0]):
                pick = i
    if pick == -1:
        return -1
    start = free_list[pick][0]
    free_list[pick][0] += size
    free_list[pick][1] -= size
    if free_list[pick][1] == 0:
        del free_list[pick]
    free_list.sort(key=lambda hole: (hole[1], hole[0]))
    return start

blocks = [[100, 60], [300, 120], [500, 80], [700, 200]]
for need in [70, 100, 150, 60, 45, 100]:
    print(need, best_fit_alloc(blocks, need))
